<?php
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
require __DIR__ . '/payment_ledger_test.php'; // Connection-local temporary fixtures only.
require_once __DIR__ . '/../include/payment_settlement.php';
$startChecks=$checks;
$invoice=$fixtureInvoice;
$invoice['invoice_id']=990001; $invoice['customer_id']=381; $invoice['service_type']='CA';
$invoice['invoice_type']='final'; $invoice['is_deleted']='No'; $invoice['final_amount']='100.00';
$db->prepare('INSERT INTO invoice_details (`'.implode('`,`',array_keys($invoice)).'`) VALUES ('.implode(',',array_fill(0,count($invoice),'?')).')')->execute(array_values($invoice));
$receipt=aitf_payment_save($db,381,[['key'=>'settlement_receipt_one','header'=>'CA','received'=>88,'tds'=>2,'date'=>'01.10.2026']]);
$receiptId=$receipt['rows'][0]['id'];
$snapshot=aitf_settlement_snapshot($db,381,'CA');
check($snapshot['remaining']==='10.00' && $snapshot['kind']==='short','Positive balance uses only selected header, including TDS');
$request=['service_type'=>'CA','discount_amount'=>10,'expected_remaining'=>10,'settlement_key'=>'short_settle_key_one','invoice_id'=>990001,'discount_date'=>'02.10.2026'];
$settled=aitf_payment_settle($db,381,$request);
check($settled['kind']==='short' && $settled['remaining']==='0.00','Short settlement clears positive balance');
$q=$db->prepare('SELECT * FROM payment_system WHERE payment_id=?');$q->execute([$settled['payment_id']]);$adjustment=$q->fetch(PDO::FETCH_ASSOC);
check($adjustment['payment_header']==='CA' && $adjustment['cheque_details']==='Short settle' && (float)$adjustment['payment_received']===0.0 && (float)$adjustment['discount_amount']===10.0,'Short settle is a labelled adjustment in the same header');
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='0.00','Reload keeps short settlement balance at zero');
$retry=aitf_payment_settle($db,381,$request);check($retry['payment_id']===$settled['payment_id'] && $retry['replayed'],'Lost response retry reuses settlement');
$bad=$request;$bad['settlement_key']='another_settle_key';$bad['expected_remaining']=0;
rejected(function()use($db,$bad){aitf_payment_settle($db,381,$bad);},'Already settled header rejects another adjustment');
$q->execute([$receiptId]);check((float)$q->fetch(PDO::FETCH_ASSOC)['payment_received']===88.0,'Cash received is not changed by short settlement');
aitf_payment_delete($db,381,$settled['payment_id'],0);
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='10.00','Deleting unverified settlement restores prior balance');
$bad=$request;$bad['discount_amount']=11;
rejected(function()use($db,$bad){aitf_payment_settle($db,381,$bad);},'Reject settlement greater than header shortfall');
$bad=$request;$bad['expected_remaining']=-10;
rejected(function()use($db,$bad){aitf_payment_settle($db,381,$bad);},'Reject stale balance or direction');
$bad=$request;$bad['invoice_id']=1760;
rejected(function()use($db,$bad){aitf_payment_settle($db,381,$bad);},'Reject another customer invoice');
$duplicate=aitf_payment_change_header($db,381,'createPaymentHeader',['service_type'=>'CA']);
$other=aitf_payment_save($db,381,[['key'=>'settlement_other_cycle','header'=>$duplicate['service_type'],'received'=>500]]);
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='10.00','Namesake header receipts do not affect settlement');
$request['discount_amount']=2;$request['settlement_key']='partial_settle_key';
$partialShort=aitf_payment_settle($db,381,$request);
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='8.00','Partial short settlement reduces only entered amount');
// Increase actual received to 110; with TDS 2 and prior short adjustment 2, excess is 14.
aitf_payment_save($db,381,[['id'=>$receiptId,'version'=>0,'header'=>'CA','received'=>110,'tds'=>2,'date'=>'01.10.2026']]);
$snapshot=aitf_settlement_snapshot($db,381,'CA');
check($snapshot['remaining']==='-14.00' && $snapshot['kind']==='excess','Negative balance identifies excess payment');
$excess=['service_type'=>'CA','discount_amount'=>14,'expected_remaining'=>-14,'settlement_key'=>'excess_settle_key','discount_date'=>'02.10.2026'];
$result=aitf_payment_settle($db,381,$excess);
$q->execute([$result['payment_id']]);$adjustment=$q->fetch(PDO::FETCH_ASSOC);
check($adjustment['cheque_details']==='Excess settle' && (float)$adjustment['discount_amount']===-14.0 && (float)$adjustment['payment_received']===0.0,'Excess adjustment has the opposite sign without negative cash receipt');
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='0.00','Excess settlement clears balance on reload');
check(aitf_settlement_snapshot($db,381,$duplicate['service_type'])['remaining']==='-500.00','Other cycle balance remains unchanged');
rejected(function()use($db,$result,$duplicate){aitf_payment_move_receipt($db,381,$result['payment_id'],$duplicate['service_type'],0);},'Settlement cannot be moved away from its header');
rejected(function()use($db,$result){aitf_payment_save($db,381,[['id'=>$result['payment_id'],'version'=>0,'header'=>'CA','received'=>1]]);},'Settlement cannot be edited as cash received');
$verified=aitf_payment_verify($db,$result['payment_id'],'Verified','reconciliation');
check($verified['locked'],'Negative adjustment can be verified');
rejected(function()use($db,$result){aitf_payment_delete($db,381,$result['payment_id'],1);},'Verified settlement is protected');
aitf_payment_verify($db,$result['payment_id'],'Verify','reconciliation');
aitf_payment_delete($db,381,$result['payment_id'],2);
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='-14.00','Deleting excess settlement restores excess balance');
$excess['settlement_key']='partial_excess_key';$excess['discount_amount']=4;
$partialExcess=aitf_payment_settle($db,381,$excess);
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='-10.00','Partial excess settlement moves negative balance towards zero');
$wrongHeader=$excess;$wrongHeader['service_type']=$duplicate['service_type'];$wrongHeader['expected_remaining']=-500;$wrongHeader['invoice_id']=990001;$wrongHeader['settlement_key']='wrong_header_invoice_key';
rejected(function()use($db,$wrongHeader){aitf_payment_settle($db,381,$wrongHeader);},'Reject invoice from another header of the same customer');
// Legacy multi-cycle grouping must match the account view before explicit headers exist.
$db->exec("INSERT INTO service (customer_id,service_type,is_deleted) VALUES (381,'CR','NO'),(381,'RC','NO')");
$db->prepare('UPDATE payment_system SET payment_header=NULL,service_type=?,payment_date=? WHERE payment_id=?')->execute(['RC','2024-04-19',$other['rows'][0]['id']]);
check(aitf_settlement_snapshot($db,381,'Till Sep 2026')['remaining']==='-500.00','Historical receipts use the same Till Sep 2026 grouping as the account page');
$edit=['id'=>$partialExcess['payment_id'],'version'=>0,'header'=>'CA','received'=>0,'tds'=>0,'settlement_amount'=>'6.50','date'=>'03.10.2026','instrument'=>'Excess settle corrected'];
$edited=aitf_payment_save($db,381,[$edit]);
$q->execute([$partialExcess['payment_id']]);$saved=$q->fetch(PDO::FETCH_ASSOC);
check((float)$saved['discount_amount']===-6.5 && (float)$saved['payment_received']===0.0,'Editing excess amount preserves its adjustment sign without creating cash');
check($saved['payment_date']==='2026-10-03' && $saved['cheque_details']==='Excess settle corrected' && $saved['reconciliation']==='Verify','Settlement date and instrument editable without reconciliation');
check(aitf_settlement_snapshot($db,381,'CA')['remaining']==='-7.50','Edited excess settlement recalculates balance');
rejected(function()use($db,$edit){aitf_payment_save($db,381,[$edit]);},'Stale settlement edits rejected');
$edit['version']=$edited['rows'][0]['version'];$edit['settlement_amount']=-1;
rejected(function()use($db,$edit){aitf_payment_save($db,381,[$edit]);},'Negative displayed settlement amount rejected');
$shortEdit=['id'=>$partialShort['payment_id'],'version'=>0,'header'=>'CA','received'=>0,'tds'=>0,'settlement_amount'=>3,'date'=>'03.10.2026','instrument'=>'Short settle'];
aitf_payment_save($db,381,[$shortEdit]);$q->execute([$partialShort['payment_id']]);
check((float)$q->fetch(PDO::FETCH_ASSOC)['discount_amount']===3.0,'Editing short settlement preserves positive sign');
echo 'PASS: '.($checks-$startChecks)." settlement checks (temporary tables only).\n";
